PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;

CREATE TABLE "absensis" ("id" integer primary key autoincrement not null, "jurnal_id" integer not null, "siswa_id" integer not null, "status" varchar check ("status" in ('H', 'S', 'I', 'A', 'D')) not null default 'H', "catatan" text, "created_at" datetime, "updated_at" datetime, foreign key("jurnal_id") references "jurnals"("id") on delete cascade, foreign key("siswa_id") references "siswas"("id") on delete cascade);

CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));

CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));

CREATE TABLE "dispensasis" ("id" integer primary key autoincrement not null, "siswa_id" integer not null, "tanggal" date not null, "jam_mulai_id" integer not null, "jam_selesai_id" integer not null, "alasan" text not null, "bukti" varchar, "status_piket" varchar check ("status_piket" in ('Menunggu', 'Disetujui', 'Ditolak')) not null default 'Menunggu', "piket_id" integer, "verified_piket_at" datetime, "status_admin" varchar check ("status_admin" in ('Menunggu', 'Disetujui', 'Ditolak')) not null default 'Menunggu', "admin_id" integer, "verified_admin_at" datetime, "status_akhir" varchar check ("status_akhir" in ('Menunggu', 'Disetujui', 'Ditolak')) not null default 'Menunggu', "catatan_verifikasi" text, "created_at" datetime, "updated_at" datetime, "group_key" varchar, foreign key("siswa_id") references "siswas"("id") on delete cascade, foreign key("jam_mulai_id") references "jam_pelajarans"("id") on delete restrict, foreign key("jam_selesai_id") references "jam_pelajarans"("id") on delete restrict, foreign key("piket_id") references "users"("id") on delete set null, foreign key("admin_id") references "users"("id") on delete set null);

CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);

CREATE TABLE "guru_mapel" ("id" integer primary key autoincrement not null, "guru_id" integer not null, "mapel_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("guru_id") references "gurus"("id") on delete cascade, foreign key("mapel_id") references "mapels"("id") on delete cascade);

CREATE TABLE "gurus" ("id" integer primary key autoincrement not null, "user_id" integer not null, "nip" varchar not null, "nama_guru" varchar not null, "no_hp" varchar, "status_kepegawaian" varchar check ("status_kepegawaian" in ('PNS', 'PPPK', 'Honorer')) not null default 'Honorer', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);

CREATE TABLE "jadwals" ("id" integer primary key autoincrement not null, "guru_id" integer not null, "kelas_id" integer not null, "mapel_id" integer not null, "jam_pelajaran_id" integer not null, "hari" varchar check ("hari" in ('Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu')) not null, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("guru_id") references "gurus"("id") on delete restrict, foreign key("kelas_id") references "kelas"("id") on delete restrict, foreign key("mapel_id") references "mapels"("id") on delete restrict, foreign key("jam_pelajaran_id") references "jam_pelajarans"("id") on delete restrict);

CREATE TABLE "jam_pelajarans" ("id" integer primary key autoincrement not null, "jam_ke" integer not null, "jam_mulai" time not null, "jam_selesai" time not null, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, "jam_mulai_jumat" time, "jam_selesai_jumat" time);

CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));

CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);

CREATE TABLE "jurnals" ("id" integer primary key autoincrement not null, "guru_id" integer not null, "kelas_id" integer not null, "mapel_id" integer not null, "jam_mulai_id" integer not null, "jam_selesai_id" integer not null, "tanggal" date not null, "status_guru" varchar check ("status_guru" in ('Hadir', 'Izin', 'Sakit', 'Dinas', 'Tanpa Keterangan')) not null default 'Hadir', "materi" varchar not null, "kegiatan" text, "tugas" text, "status_verifikasi" varchar check ("status_verifikasi" in ('Menunggu', 'Disetujui', 'Ditolak')) not null default 'Menunggu', "tanda_tangan" varchar, "created_at" datetime, "updated_at" datetime, "tujuan_pembelajaran" text, "catatan" text, foreign key("guru_id") references "gurus"("id") on delete cascade, foreign key("kelas_id") references "kelas"("id") on delete restrict, foreign key("mapel_id") references "mapels"("id") on delete restrict, foreign key("jam_mulai_id") references "jam_pelajarans"("id") on delete restrict, foreign key("jam_selesai_id") references "jam_pelajarans"("id") on delete restrict);

CREATE TABLE "kelas" ("id" integer primary key autoincrement not null, "nama_kelas" varchar not null, "tingkat" varchar not null, "created_at" datetime, "updated_at" datetime, "wali_kelas_id" integer, foreign key("wali_kelas_id") references "gurus"("id") on delete set null);

CREATE TABLE "mapels" ("id" integer primary key autoincrement not null, "kode_mapel" varchar not null, "nama_mapel" varchar not null, "keterangan" text, "created_at" datetime, "updated_at" datetime);

CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);

CREATE TABLE "notifications" ("id" varchar not null, "type" varchar not null, "notifiable_type" varchar not null, "notifiable_id" integer not null, "data" text not null, "read_at" datetime, "created_at" datetime, "updated_at" datetime, primary key ("id"));

CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));

CREATE TABLE "registration_requests" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "password" varchar not null, "role" varchar check ("role" in ('guru', 'siswa', 'sekretaris', 'piket')) not null, "status" varchar check ("status" in ('pending', 'approved', 'rejected')) not null default 'pending', "rejection_reason" text, "reviewed_by" integer, "reviewed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("reviewed_by") references "users"("id") on delete set null);

CREATE TABLE "sekretaris_kelas" ("id" integer primary key autoincrement not null, "user_id" integer not null, "kelas_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("kelas_id") references "kelas"("id") on delete cascade);

CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));

CREATE TABLE "siswas" ("id" integer primary key autoincrement not null, "user_id" integer not null, "kelas_id" integer not null, "nis" varchar not null, "nama_siswa" varchar not null, "jenis_kelamin" varchar check ("jenis_kelamin" in ('L', 'P')) not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("kelas_id") references "kelas"("id") on delete restrict);

CREATE TABLE "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "role" varchar check ("role" in ('guru', 'siswa', 'sekretaris', 'piket', 'admin')) not null, "is_active" tinyint(1) not null default '1', "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "username" varchar);

CREATE TABLE "verifikasi_jurnals" ("id" integer primary key autoincrement not null, "jurnal_id" integer not null, "verifikator_id" integer, "status" varchar check ("status" in ('Disetujui', 'Ditolak')) not null, "catatan" text, "verified_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("jurnal_id") references "jurnals"("id") on delete cascade, foreign key("verifikator_id") references "users"("id") on delete set null);

CREATE UNIQUE INDEX "absensis_jurnal_id_siswa_id_unique" on "absensis" ("jurnal_id", "siswa_id");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "dispensasis_group_key_index" on "dispensasis" ("group_key");
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "guru_mapel_guru_id_mapel_id_unique" on "guru_mapel" ("guru_id", "mapel_id");
CREATE UNIQUE INDEX "gurus_nip_unique" on "gurus" ("nip");
CREATE UNIQUE INDEX "gurus_user_id_unique" on "gurus" ("user_id");
CREATE INDEX "jadwals_hari_jam_pelajaran_id_index" on "jadwals" ("hari", "jam_pelajaran_id");
CREATE UNIQUE INDEX "jam_pelajarans_jam_ke_unique" on "jam_pelajarans" ("jam_ke");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "kelas_nama_kelas_unique" on "kelas" ("nama_kelas");
CREATE UNIQUE INDEX "mapels_kode_mapel_unique" on "mapels" ("kode_mapel");
CREATE INDEX "notifications_notifiable_type_notifiable_id_index" on "notifications" ("notifiable_type", "notifiable_id");
CREATE INDEX "registration_requests_email_index" on "registration_requests" ("email");
CREATE INDEX "registration_requests_status_index" on "registration_requests" ("status");
CREATE UNIQUE INDEX "sekretaris_kelas_user_id_kelas_id_unique" on "sekretaris_kelas" ("user_id", "kelas_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE UNIQUE INDEX "siswas_nis_unique" on "siswas" ("nis");
CREATE UNIQUE INDEX "siswas_user_id_unique" on "siswas" ("user_id");
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE UNIQUE INDEX "users_username_unique" on "users" ("username");

CREATE TABLE "activity_logs" ("id" integer primary key autoincrement not null, "user_id" integer, "action" varchar not null, "description" text not null, "metadata" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null);

ALTER TABLE "jurnals" ADD "attendance_witnesses" text;

COMMIT;
PRAGMA foreign_keys=ON;
